SELECT COUNT(flrc_type) AS SumTotal, COUNT(flrc_type = 3 OR NULL ) AS Inland, COUNT(flrc_type = 1 OR NULL ) AS InterNational, COUNT(flrc_type = 2 OR NULL ) AS Lcountry FROM T_FUEL_RECPT WHERE DATE_FORMAT(flrc_rec_cre_time,'%Y-%m-%d')=CURDATE()
and flrc_aptarea_code=#{staffAptareaCode}
and flrc_airport_code=#{staffAirportCode}

SELECT SUM(flrc_fuel_vol) AS flrcFuelVol, SUM(flrc_quantity/1000) AS flrcQuantity FROM T_FUEL_RECPT WHERE DATE_FORMAT(flrc_rec_cre_time,'%Y-%m-%d')=CURDATE()
and flrc_aptarea_code=#{staffAptareaCode}
and flrc_airport_code=#{staffAirportCode}

SELECT flrc_id AS flrcId,flrc_type AS flrcType,flrc_no AS flrcNo, flrc_date AS flrcDate, flrc_airport_code AS flrcAirportCode,flrc_aptarea_code AS flrcAptareaCode,flrc_airport AS flrcAirport, flrc_airl_name AS flrcAirlName,flrc_flight_no AS flrcFlightNo,flrc_aircrft_no AS flrcAircrftNo, flrc_aircrft_type AS flrcAircrftType , flrc_departure AS flrcDeparture, flrc_transit AS flrcTransit,flrc_dest AS flrcDest ,flrc_test_bill_no AS flrcTestBillNo, flrc_fuel_name AS flrcFuelName,flrc_fuel_temp AS flrcFuelTemp,flrc_fuel_dnst AS flrcFuelDnst, flrc_fuel_vol AS flrcFuelVol,flrc_meter_stat AS flrcMeterStat,flrc_meter_fnsh AS flrcMeterFnsh, flrc_figuars AS flrcFiguars,flrc_figuars_word AS flrcFiguarsWord ,flrc_quantity AS flrcQuantity, flrc_vehi_no AS flrcVehiNo ,flrc_hydrt_pit_no AS flrcHydrtPitNo,flrc_stat_time AS flrcStatTime, flrc_fnsh_time AS flrcFnshTime,flrc_deliver_name AS flrcDeliverName,flrc_sign AS flrcSign, flrc_manual_tag AS flrcManualTag,flrc_manual_staff AS flrcManualStaff ,flrc_manual_time AS flrcManualTime, flrc_revw_status AS flrcRevwStatus ,flrc_takeback_flg AS flrcTakebackFlg,flrc_rec_cre_time AS flrcRecCreTime FROM T_FUEL_RECPT WHERE flrc_date >= date_sub(curdate(), INTERVAL 7 DAY)
AND flrc_airport_code = #{ staffAirportCode }
AND flrc_aptarea_code=#{staffAptareaCode}

SELECT flrc_id AS flrcId,flrc_type AS flrcType,flrc_no AS flrcNo, flrc_date AS flrcDate, flrc_airport_code AS flrcAirportCode,flrc_aptarea_code AS flrcAptareaCode,flrc_airport AS flrcAirport, flrc_airl_name AS flrcAirlName,flrc_flight_no AS flrcFlightNo,flrc_aircrft_no AS flrcAircrftNo, flrc_aircrft_type AS flrcAircrftType , flrc_departure AS flrcDeparture, flrc_transit AS flrcTransit,flrc_dest AS flrcDest ,flrc_test_bill_no AS flrcTestBillNo, flrc_fuel_name AS flrcFuelName,flrc_fuel_temp AS flrcFuelTemp,flrc_fuel_dnst AS flrcFuelDnst, flrc_fuel_vol AS flrcFuelVol,flrc_meter_stat AS flrcMeterStat,flrc_meter_fnsh AS flrcMeterFnsh, flrc_figuars AS flrcFiguars,flrc_figuars_word AS flrcFiguarsWord ,flrc_quantity AS flrcQuantity, flrc_vehi_no AS flrcVehiNo ,flrc_hydrt_pit_no AS flrcHydrtPitNo,flrc_stat_time AS flrcStatTime, flrc_fnsh_time AS flrcFnshTime,flrc_deliver_name AS flrcDeliverName,flrc_sign AS flrcSign, flrc_manual_tag AS flrcManualTag,flrc_manual_staff AS flrcManualStaff ,flrc_manual_time AS flrcManualTime, flrc_revw_status AS flrcRevwStatus ,flrc_takeback_flg AS flrcTakebackFlg,flrc_rec_cre_time AS flrcRecCreTime FROM T_FUEL_RECPT WHERE DATE_FORMAT(flrc_date,'%Y-%m-%d') = curdate()
