flrc_airport_code AS flrcAirportCode,flrc_aptarea_code AS flrcAptareaCode,flrc_airport AS flrcAirport,
flrc_airl_name AS flrcAirlName,flrc_flight_no AS flrcFlightNo,flrc_aircrft_no AS flrcAircrftNo,
flrc_aircrft_type AS flrcAircrftType , flrc_departure AS flrcDeparture,
flrc_transit AS flrcTransit,flrc_dest AS flrcDest ,flrc_test_bill_no AS flrcTestBillNo,
flrc_fuel_name AS flrcFuelName,flrc_fuel_temp AS flrcFuelTemp,flrc_fuel_dnst AS flrcFuelDnst,
flrc_fuel_vol AS flrcFuelVol,flrc_meter_stat AS flrcMeterStat,flrc_meter_fnsh AS flrcMeterFnsh,
