    AND flrc_hydrt_pit_no=#{flrcHydrtPitNo}


    AND flrc_stat_time=#{flrcStatTime}


    AND flrc_fnsh_time =#{flrcFnshTime}


    AND flrc_deliver_name=#{flrcDeliverName}


    AND flrc_sign=#{flrcSign}


    AND flrc_manual_tag=#{flrcManualTag}


    AND flrc_manual_staff=#{flrcManualStaff}


